require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('donor');$error=null;
if(request_method('POST')){Csrf::verify();$organ=$_POST['organ_type']??'';$action=$_POST['action']??'add';if(!in_array($organ,organ_types(),true))$error='Select a valid interest type.';else{if($action==='withdraw'){db()->prepare("UPDATE organ_interests SET status='withdrawn' WHERE donor_id=? AND organ_type=?")->execute([(int)$user['id'],$organ]);audit('organ_interest_withdrawn','user',(int)$user['id'],['organ'=>$organ]);}else{db()->prepare("INSERT INTO organ_interests(donor_id,organ_type,status) VALUES(?,?,'active') ON DUPLICATE KEY UPDATE status='active',updated_at=NOW()")->execute([(int)$user['id'],$organ]);audit('organ_interest_added','user',(int)$user['id'],['organ'=>$organ]);}flash('success','Organ-interest record updated.');redirect('donor/organ-interest.php');}}
$q=db()->prepare('SELECT * FROM organ_interests WHERE donor_id=? ORDER BY organ_type');$q->execute([(int)$user['id']]);$rows=$q->fetchAll();$pageTitle='Organ Interest';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Restricted voluntary record</div><h1>Organ-donation interest</h1><p class="page-note">This page records voluntary interest only. It is not a donor registry decision, medical suitability assessment or transplant allocation.</p></div></div><?=donor_nav()?><div class="grid-2"><div class="card"><h2>Add an interest</h2><?php if($error):?><div class="error-list"><?=e($error)?></div><?php endif;?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="add"><div class="field"><label>Interest type</label><select name="organ_type" required><option value="">Select</option><?php foreach(organ_types() as $o):?><option><?=e($o)?></option><?php endforeach;?></select></div><button class="btn">Record Interest</button></form><div class="danger-note"><strong>Important:</strong> hospitals with special authorization can view only limited coordination information from this module.</div></div><div><h2>Your records</h2><div class="table-wrap"><table class="table"><thead><tr><th>Type</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4" class="empty">No organ-interest records.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['organ_type'])?></td><td><span class="badge <?=$r['status']==='active'?'green':'gray'?>"><?=e($r['status'])?></span></td><td><?=e($r['updated_at'])?></td><td><?php if($r['status']==='active'):?><form method="post"><?=Csrf::field()?><input type="hidden" name="organ_type" value="<?=e($r['organ_type'])?>"><button class="btn btn-outline btn-sm" name="action" value="withdraw">Withdraw</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section>
